const char* mrhiResultName(mrhiResult result)
{
    switch (result)
    {
    case mrhi_success:
        return "mrhi_success";
    case mrhi_errorInvalid:
        return "mrhi_errorInvalid";
    case mrhi_errorCapacity:
        return "mrhi_errorCapacity";
    case mrhi_errorStale:
        return "mrhi_errorStale";
    case mrhi_errorUnsupported:
        return "mrhi_errorUnsupported";
    case mrhi_errorPlatform:
        return "mrhi_errorPlatform";
    case mrhi_errorState:
        return "mrhi_errorState";
    case mrhi_errorVersion:
        return "mrhi_errorVersion";
    default:
        return "unknown result";
    }
}
